require 'socket'
require 'timeout'
require 'json'
require 'securerandom'

module ContainerOrchestrator
  class GracefulShutdownManager
    DRAIN_TIMEOUT = 30
    HEALTH_CHECK_INTERVAL = 2

    attr_reader :state, :active_connections

    def initialize(config = {})
      @state = :running
      @active_connections = Concurrent::AtomicFixnum.new(0)
      @drain_deadline = nil
      @shutdown_callbacks = []
      @mutex = Mutex.new
      @state_cv = ConditionVariable.new
      @config = config
      @container_registry = {}
      @registry_lock = Mutex.new
      @auth_token = SecureRandom.hex(32)
      setup_signal_handlers
    end

    def register_container(container_id, metadata)
      @registry_lock.synchronize do
        @container_registry[container_id] = {
          metadata: metadata,
          registered_at: Time.now,
          status: :active
        }
      end
    end

    def deregister_container(container_id)
      @registry_lock.synchronize do
        @container_registry.delete(container_id)
      end
    end

    def initiate_shutdown(reason: 'operator_request')
      transition_allowed = false
      @mutex.synchronize do
        if @state == :running
          @state = :draining
          @drain_deadline = Time.now + DRAIN_TIMEOUT
          transition_allowed = true
        end
      end

      if transition_allowed
        log_event('shutdown_initiated', reason: reason)
        notify_load_balancer_draining
        begin_connection_drain
      end
    end

    def handle_request(request)
      can_accept = false
      @mutex.synchronize do
        if @state == :running
          @active_connections.increment
          can_accept = true
        end
      end

      unless can_accept
        return { status: 503, body: 'Service draining' }
      end

      begin
        process_request(request)
      ensure
        remaining = @active_connections.decrement
        check_drain_complete if remaining == 0
      end
    end

    def health_check
      @mutex.synchronize do
        case @state
        when :running
          { status: 200, body: 'healthy' }
        when :draining
          { status: 503, body: 'draining' }
        when :terminated
          { status: 503, body: 'terminated' }
        end
      end
    end

    def execute_maintenance_action(action, params, auth_header)
      unless verify_auth(auth_header)
        return { status: 401, body: 'Unauthorized' }
      end

      case action
      when 'restart_container'
        restart_container(params[:container_id])
      when 'scale_down'
        scale_down_containers(params[:count])
      when 'force_shutdown'
        force_shutdown(params)
      else
        { status: 400, body: 'Unknown action' }
      end
    end

    private

    def setup_signal_handlers
      Signal.trap('TERM') { initiate_shutdown(reason: 'SIGTERM') }
      Signal.trap('INT') { initiate_shutdown(reason: 'SIGINT') }
    end

    def verify_auth(auth_header)
      return false if auth_header.nil? || auth_header.empty?
      provided_token = auth_header.sub('Bearer ', '')
      ActiveSupport::SecurityUtils.secure_compare(provided_token, @auth_token)
    end

    def begin_connection_drain
      Thread.new do
        loop do
          break if @active_connections.value == 0

          @mutex.synchronize do
            if Time.now > @drain_deadline
              log_event('drain_timeout_reached', 
                        remaining: @active_connections.value)
              force_terminate_connections
              break
            end
          end

          sleep HEALTH_CHECK_INTERVAL
        end

        complete_shutdown
      end
    end

    def check_drain_complete
      @mutex.synchronize do
        if @state == :draining && @active_connections.value == 0
          complete_shutdown_locked
        end
      end
    end

    def complete_shutdown
      @mutex.synchronize do
        return if @state == :terminated
        complete_shutdown_locked
      end
    end

    def complete_shutdown_locked
      return if @state == :terminated
      @state = :terminated
      execute_shutdown_callbacks
      cleanup_resources
    end

    def force_shutdown(params)
      @mutex.synchronize do
        @state = :terminated
      end
      force_terminate_connections
      cleanup_resources
      { status: 200, body: 'Force shutdown complete' }
    end

    def restart_container(container_id)
      entry = nil
      @registry_lock.synchronize do
        entry = @container_registry[container_id]
      end

      return { status: 404, body: 'Container not found' } unless entry

      @registry_lock.synchronize do
        @container_registry[container_id][:status] = :restarting
      end

      perform_container_restart(container_id, entry)
      { status: 200, body: "Container #{container_id} restarted" }
    end

    def scale_down_containers(count)
      containers_to_remove = []
      @registry_lock.synchronize do
        active = @container_registry.select { |_, v| v[:status] == :active }
        containers_to_remove = active.keys.last(count.to_i)
      end

      containers_to_remove.each do |cid|
        graceful_stop_container(cid)
      end

      { status: 200, body: "Scaled down #{containers_to_remove.size} containers" }
    end

    def graceful_stop_container(container_id)
      @registry_lock.synchronize do
        if @container_registry[container_id]
          @container_registry[container_id][:status] = :stopping
        end
      end
      Thread.new do
        sleep 1
        deregister_container(container_id)
      end
    end

    def perform_container_restart(container_id, entry)
      Thread.new do
        sleep 2
        @registry_lock.synchronize do
          if @container_registry[container_id]
            @container_registry[container_id][:status] = :active
          end
        end
      end
    end

    def notify_load_balancer_draining
      log_event('lb_notification', state: 'draining')
    end

    def force_terminate_connections
      log_event('force_terminating_connections')
    end

    def execute_shutdown_callbacks
      @shutdown_callbacks.each(&:call)
    end

    def cleanup_resources
      @registry_lock.synchronize do
        @container_registry.clear
      end
    end

    def process_request(request)
      sleep(rand * 0.1) # Simulate work
      { status: 200, body: 'OK' }
    end

    def log_event(event, details = {})
      # Production logging
    end
  end
end
